  "giaiThich": "不如 là ĐỘNG TỪ, biểu thị \"so không bằng\" (比不上): A 不如 B = A kém B. Sau B có thể thêm tính từ mang nghĩa TÍCH CỰC (好 / 高 / 快 / 便宜) hoặc kết thúc câu luôn (求人不如求己, 我的发音不如她). Hay đi với 还 / 连……都 để nhấn mạnh: 还不如, 连……都不如. Ngoài ra, ……，不如…… dùng để đề xuất một lựa chọn tốt hơn (= chi bằng): 在房间睡觉不如出去走走. Không dùng chung với 比, không đặt tính từ tiêu cực sau B.",
